+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const STORE_FILE = path.join(process.cwd(), ".session-store.json");
+
+const getStore = (): Map<string, Entry> => {
+  const store = new Map<string, Entry>();
+
+  if (fs.existsSync(STORE_FILE)) {
+    try {
+      const data = JSON.parse(fs.readFileSync(STORE_FILE, "utf-8"));
+      Object.entries(data).forEach(([key, entry]: [string, any]) => {
+        store.set(key, entry);
+      });
+    } catch {
+      // If store file is corrupted, start fresh
+    }
+  }
+
+  return store;
+};
+
+const saveStore = (store: Map<string, Entry>): void => {
+  const data: Record<string, Entry> = {};
+  store.forEach((entry, key) => {
+    if (entry.expiresAt > Date.now()) {
+      data[key] = entry;
+    }
+  });
+  fs.writeFileSync(STORE_FILE, JSON.stringify(data));
+};

 export const put = (key: string, value: string, ttlMs: number): void => {
+  const store = getStore();
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveStore(store);
 };

 export const get = (key: string): string | null => {
+  const store = getStore();
   const entry = store.get(key);
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
     store.delete(key);
+    saveStore(store);
     return null;
   }
   return entry.value;
